const {chromium}=require('playwright');const U='http://localhost:8765/';
(async()=>{const b=await chromium.launch();const ok=(n,c)=>console.log((c?'PASS ':'FAIL ')+n);const errs=[];
for(const w of [1366,390]){const p=await b.newPage({viewport:{width:w,height:w>500?800:844}});p.on('pageerror',e=>errs.push(e.message));
await p.goto(U);await p.evaluate(()=>localStorage.clear());await p.reload();await p.waitForTimeout(600);
ok(w+' no tab row',!(await p.locator('nav.nav').count()));
const L=async()=>p.evaluate(()=>{const b=document.querySelector('#people [aria-pressed="true"]');return b?b.textContent.trim():'none'});
ok(w+' Patient selected '+await L(),await L()==='Patient');
const tops=await p.evaluate(()=>[...document.querySelectorAll('.top .demo-btn')].map(b=>Math.round(b.getBoundingClientRect().top)));
if(w>500) ok(w+' one row '+tops,new Set(tops).size===1);
await p.screenshot({path:`bar-${w}.png`,clip:{x:0,y:0,width:w,height:w>500?110:150}});
await p.click('#people [data-e="1"]');await p.waitForTimeout(400);ok(w+' Noura label '+await L(),await L()==='Coordinator · Noura');
await p.click('#people [data-e="4"]');await p.waitForTimeout(400);ok(w+' Khalid label',await L()==='Programme lead · Dr. Khalid');
await p.click('#people [data-e="0"]');await p.waitForTimeout(400);await p.click('[data-pick="C-1049"]');await p.waitForTimeout(500);ok(w+' Mariam: Patient chip + Mariam picked',await L()==='Patient'&&await p.getAttribute('[data-pick="C-1049"]','aria-pressed')==='true');await p.screenshot({path:`panel-${w}.png`,fullPage:true});
await p.click('#aboutBtn');await p.waitForTimeout(150);ok(w+' about menu',await p.isVisible('#aboutMenu')&&/How it works/.test(await p.locator('#aboutMenu').innerText()));
await p.screenshot({path:`about-${w}.png`});
await p.keyboard.press('Escape');ok(w+' about Esc',!(await p.locator('#aboutMenu').count()));
await p.click('#aboutBtn');await p.mouse.click(5,w>500?700:800);ok(w+' about outside',!(await p.locator('#aboutMenu').count()));
await p.click('#aboutBtn');await p.click('#aboutMenu [data-h="#/about"]');await p.waitForTimeout(300);ok(w+' about route + Choose label',p.url().endsWith('#/about')&&await L()==='none');
await p.click('#aboutBtn');await p.click('#aboutMenu [data-h="#/safety"]');await p.waitForTimeout(300);ok(w+' safety route',p.url().endsWith('#/safety'));
await p.click('#tourBtn');await p.waitForTimeout(800);ok(w+' tour follows: Fatima chip',await L()==='Patient');await p.click('#tour [data-t=step][data-i="4"]');await p.waitForTimeout(800);ok(w+' tour step 5: Rajesh picked',await L()==='Patient'&&await p.getAttribute('[data-pick="C-1043"]','aria-pressed')==='true');await p.click('#tour [data-t=step][data-i="3"]');await p.waitForTimeout(800);ok(w+' tour step 4: Specialist chip',await L()==='Specialist · Dr. Omar');await p.click('#tourBtn');
ok(w+' no h-scroll',!(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth)));
await p.close();}
console.log('errors',errs);await b.close()})();
